from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
R,G,B=im.T
# thresholds and print white mask in crop 40:220 x 40:220? at each pixel downsample 2
white=((R>170)&(G>170)&(B>150)).T
for y0,y1 in [(145,210),(220,255),(90,150)]:
 print('\\nY',y0,y1)
 for y in range(y0,y1,2):
  s=f'{y:3d} '
  for x in range(40,220,2):
   block=white[y:y+2,x:x+2]
   n=block.sum()
   s += str(n) if n else ' '
  print(s)
# connected components of white rough
from collections import deque
H,W=white.shape; seen=np.zeros_like(white,bool)
for y in range(H):
 for x in range(W):
  if white[y,x] and not seen[y,x]:
   q=[(y,x)]; seen[y,x]=1; pts=[]
   for cy,cx in q:
    pts.append((cy,cx))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      if dy==dx==0: continue
      ny,nx=cy+dy,cx+dx
      if 0<=ny<H and 0<=nx<W and white[ny,nx] and not seen[ny,nx]:
       seen[ny,nx]=1;q.append((ny,nx))
   if len(pts)>3:
    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
    print('comp',len(pts),(min(xs),min(ys),max(xs),max(ys)), 'mean',np.mean(xs),np.mean(ys))
PY"
